}

/* ---------------------------------------------------------------- v3 helpers: goal hold, savings, real-world rates */
export const GOAL_HOLD = 2; // "החופש צריך להחזיק": 2 consecutive paydays (education review §3.2)
/** Is the world goal met right now (before the 3-payday hold)? */
function goalMet(st) {
