  const leaks = leaksOf(st);
  const sold = [];
  for (const a of st.assets.slice()) if (assetCf(st, a) < 0) { bizArchive(st, a); st.cash += assetValue(st, a) - a.debt; sold.push(a.n); st.assets = st.assets.filter((x) => x !== a); out.despawn.push('a' + a.id); }
