  prepay: { operationalFee: 60, noNoticePct: 0.001, noticeDays: 10, discount3y: 0.2, discount5y: 0.3, variableEvery: 60 },
  // limits (הפיקוח על הבנקים): LTV by buyer, PTI ≤ 50%, ≥ 1/3 fixed rate, prime ≤ 2/3, ≤ 30 years
